import { compareKeys, flattenTokens, sortedEntries } from "./flatten.js";
import type { TokenFile } from "./types.js";

export interface GeneratedOutputs {
  css: string;
  tailwind: string;
}

export const GENERATED_HEADER =
  "Generated by `friday design tokens build` from tokens.json. Do not edit by hand.";

type Json = string | number | { [key: string]: Json };

function serialize(value: Json, indent: number): string {
  if (typeof value !== "object") {
    return JSON.stringify(value);
  }
  const entries = Object.entries(value).sort(([a], [b]) => compareKeys(a, b));
  if (entries.length === 0) {
    return "{}";
  }
  const pad = "  ".repeat(indent + 1);
  const lines = entries.map(([k, v]) => `${pad}${JSON.stringify(k)}: ${serialize(v, indent + 1)},`);
  return `{\n${lines.join("\n")}\n${"  ".repeat(indent)}}`;
}

function toRecord<T extends Json>(record: Record<string, T>): Record<string, Json> {
  return Object.fromEntries(sortedEntries(record));
}

/**
 * Pure and deterministic: categories follow a fixed order and keys are sorted
 * by code unit, so the same TokenFile always yields byte-identical strings.
 */
export function generateOutputs(tf: TokenFile): GeneratedOutputs {
  const cssLines = flattenTokens(tf).map((t) => `  --${t.cssName}: ${t.value};`);
  const css = `/* ${GENERATED_HEADER} */\n:root {\n${cssLines.join("\n")}\n}\n`;

  // Tailwind theme fragment: use as `presets: [tokens]` or spread into `theme.extend`.
  const extend: Record<string, Json> = {
    borderRadius: toRecord(tf.radius),
    boxShadow: toRecord(tf.elevation),
    colors: toRecord(tf.color),
    motion: toRecord(tf.motion),
    spacing: toRecord(tf.spacing),
    type: toRecord(tf.type),
  };
  const tailwind = `// ${GENERATED_HEADER}\nexport default {\n  theme: {\n    extend: ${serialize(extend, 2)},\n  },\n};\n`;
  return { css, tailwind };
}
